import os
import vertexai
from vertexai.preview.generative_models import GenerativeModel, Part, HarmCategory, HarmBlockThreshold

def moderate_text(text: str) -> dict:
    """
    Scores user text for unsafe or policy-violating content using Google Vertex AI.
    """
    project_id = os.environ.get("GOOGLE_CLOUD_PROJECT")
    location = os.environ.get("GOOGLE_CLOUD_LOCATION", "us-central1")
    model_name = "gemini-pro"

    vertexai.init(project=project_id, location=location)
    model = GenerativeModel(model_name)

    response = model.generate_content(
        [text],
        safety_settings={
            HarmCategory.HARM_CATEGORY_DANGEROUS_CONTENT: HarmBlockThreshold.BLOCK_MEDIUM_AND_ABOVE,
            HarmCategory.HARM_CATEGORY_HATE_SPEECH: HarmBlockThreshold.BLOCK_MEDIUM_AND_ABOVE,
            HarmCategory.HARM_CATEGORY_SEXUALLY_EXPLICIT: HarmBlockThreshold.BLOCK_MEDIUM_AND_ABOVE,
            HarmCategory.HARM_CATEGORY_HARASSMENT: HarmBlockThreshold.BLOCK_MEDIUM_AND_ABOVE,
        },
        stream=False,
    )

    # Extract safety attributes from the response
    safety_ratings = []
    if hasattr(response, 'candidates') and response.candidates:
        for candidate in response.candidates:
            if hasattr(candidate, 'safety_ratings'):
                for rating in candidate.safety_ratings:
                    safety_ratings.append({
                        "category": rating.category.name,
                        "probability": rating.probability.name,
                        "blocked": rating.blocked
                    })

    return {"safety_ratings": safety_ratings}

from dataclasses import dataclass, field
from typing import List, Dict, Any

@dataclass
class SafetyRating:
    category: str
    probability: str
    blocked: bool

@dataclass
class ModerationResult:
    text: str
    safety_ratings: List[SafetyRating]
    is_allowed: bool = True
    reasons: List[str] = field(default_factory=list)

@dataclass
class ThresholdConfig:
    category: str
    block_probability: str  # e.g., "HARM_BLOCK_THRESHOLD_UNSPECIFIED", "BLOCK_LOW_AND_ABOVE"

import os
import vertexai
from google.cloud import dlp_v2
from vertexai.preview.generative_models import GenerativeModel, Part, HarmCategory, HarmBlockThreshold
from typing import List, Dict, Any

class SafetyClient:
    _vertex_ai_initialized = False
    _dlp_client = None

    def __init__(self, project_id: str = None, location: str = None):
        self.project_id = project_id or os.environ.get("GOOGLE_CLOUD_PROJECT")
        self.location = location or os.environ.get("GOOGLE_CLOUD_LOCATION", "us-central1")

        if not self.project_id:
            raise ValueError("Google Cloud Project ID not provided and GOOGLE_CLOUD_PROJECT environment variable not set.")

        self._initialize_vertex_ai()

    def _initialize_vertex_ai(self):
        if not SafetyClient._vertex_ai_initialized:
            vertexai.init(project=self.project_id, location=self.location)
            SafetyClient._vertex_ai_initialized = True

    def get_generative_model(self, model_name: str = "gemini-pro") -> GenerativeModel:
        self._initialize_vertex_ai()
        return GenerativeModel(model_name)

    def get_dlp_client(self) -> dlp_v2.DlpServiceClient:
        if SafetyClient._dlp_client is None:
            SafetyClient._dlp_client = dlp_v2.DlpServiceClient()
        return SafetyClient._dlp_client

    def moderate_text_with_vertex_ai(self, text: str, model_name: str = "gemini-pro") -> dict:
        model = self.get_generative_model(model_name)
        response = model.generate_content(
            [text],
            safety_settings={
                HarmCategory.HARM_CATEGORY_DANGEROUS_CONTENT: HarmBlockThreshold.BLOCK_MEDIUM_AND_ABOVE,
                HarmCategory.HARM_CATEGORY_HATE_SPEECH: HarmBlockThreshold.BLOCK_MEDIUM_AND_ABOVE,
                HarmCategory.HARM_CATEGORY_SEXUALLY_EXPLICIT: HarmBlockThreshold.BLOCK_MEDIUM_AND_ABOVE,
                HarmCategory.HARM_CATEGORY_HARASSMENT: HarmBlockThreshold.BLOCK_MEDIUM_AND_ABOVE,
            },
            stream=False,
        )

        safety_ratings = []
        if hasattr(response, 'candidates') and response.candidates:
            for candidate in response.candidates:
                if hasattr(candidate, 'safety_ratings'):
                    for rating in candidate.safety_ratings:
                        safety_ratings.append({
                            "category": rating.category.name,
                            "probability": rating.probability.name,
                            "blocked": rating.blocked
                        })

        return {"safety_ratings": safety_ratings}

import os
from typing import List, Dict, Any
from google.cloud import dlp_v2
from safety_client import SafetyClient

def redact_unsafe(text: str, info_types: List[str] = None) -> Dict[str, Any]:
    """
    Flags or redacts unsafe spans from text using Google Cloud DLP API.
    By default, redacts common PII. Custom info_types can be provided.
    """
    if info_types is None:
        info_types = [
            "PHONE_NUMBER", "EMAIL_ADDRESS", "CREDIT_CARD_NUMBER",
            "IP_ADDRESS", "US_SOCIAL_SECURITY_NUMBER", "PASSPORT",
            "PERSON_NAME", "LOCATION", "DATE_OF_BIRTH"
        ]

    safety_client = SafetyClient()
    dlp_client = safety_client.get_dlp_client()
    project_id = safety_client.project_id

    # Construct the `inspect_config` to specify the info_types to look for
    inspect_config = {"info_types": [{"name": info_type} for info_type in info_types]}

    # Construct the `redact_config` to replace identified sensitive data with a placeholder
    redact_config = {"info_type_transformations": []}
    for info_type in info_types:
        redact_config["info_type_transformations"].append({
            "info_types": [{"name": info_type}],
            "primitive_transformation": {"character_masking_config": {"masking_character": "*"}}
        })

    # Construct the `deidentify_config`
    deidentify_config = {"info_type_transformations": redact_config["info_type_transformations"]}

    # Construct the `item` to be de-identified
    item = {"value": text}

    # Call the DLP API to de-identify the content
    response = dlp_client.deidentify_content(
        request={
            "parent": f"projects/{project_id}/locations/{safety_client.location}",
            "deidentify_config": deidentify_config,
            "inspect_config": inspect_config,
            "item": item,
        }
    )

    return {"redacted_text": response.item.value}
